const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const pakistan = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Pakistan'))
      .geometry();

    const jan2018Start = '2018-01-01';
    const jan2018End = '2018-01-31';
    const aug2018Start = '2018-08-01';
    const aug2018End = '2018-08-31';

    // 2. Data Acquisition
    const etCollection = ee.ImageCollection('MODIS/006/MOD16A2H');

    // Filter for January 2018
    let janCollection = etCollection.filterDate(jan2018Start, jan2018End)
      .select('ET')
      .filterBounds(pakistan);

    // Filter for August 2018
    let augCollection = etCollection.filterDate(aug2018Start, aug2018End)
      .select('ET')
      .filterBounds(pakistan);

    // Check for empty collections
    const janSize = await janCollection.size().getInfo();
    const augSize = await augCollection.size().getInfo();

    if (janSize === 0 || augSize === 0) {
      console.log(`January 2018 images: ${janSize}`);
      console.log(`August 2018 images: ${augSize}`);
      console.log("C1"); // Empty Collection
      return;
    }

    console.log(`January 2018 images: ${janSize}`);
    console.log(`August 2018 images: ${augSize}`);

    // Function to calculate monthly mean ET in mm
    const calculateMonthlyET = (collection, numDaysInMonth) => {
      // Scale factor for ET band (0.1 kg/m^2/8day = 0.1 mm/8day)
      // Multiply by 0.1 to convert to mm/8day
      // Multiply by number of 8-day periods in the month
      // Sum all 8-day composites in the month, then multiply by 0.1 (scale factor)
      // This gives total ET for the month in mm.
      // Or, take the mean of the 8-day composites and then multiply by numDaysInMonth.
      // Let's sum the scaled 8-day composites.

      if (collection.size().getInfo() === 0) {
        return ee.Image(0); // Return an image of 0 if collection is empty for aggregation
      }

      const scaledCollection = collection.map(image => image.multiply(0.1)); // Convert to mm/8day
      const monthlyTotal = scaledCollection.sum(); // Sum all 8-day composites for the month
      return monthlyTotal;
    };

    const janETImage = calculateMonthlyET(janCollection, 31); // 31 days in January
    const augETImage = calculateMonthlyET(augCollection, 31); // 31 days in August

    const scale = 5000; // Use a coarser scale to avoid memory issues and speed up
    const maxPixels = 1e10;

    // Calculate mean ET over Pakistan for January
    const janMeanET = await janETImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: pakistan,
      scale: scale,
      maxPixels: maxPixels
    }).get('ET').getInfo();

    // Calculate mean ET over Pakistan for August
    const augMeanET = await augETImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: pakistan,
      scale: scale,
      maxPixels: maxPixels
    }).get('ET').getInfo();

    // 3. Check for No Valid Pixels or Calculation Failure
    if (janMeanET === null || isNaN(janMeanET) || augMeanET === null || isNaN(augMeanET)) {
      console.log("C3"); // Calculation failure (NaN or None)
      return;
    }

    // To check C2 (No Valid Pixels), we can check the count before calculating mean.
    // For large areas like countries, it's rare to have 0 pixels unless the geometry is wrong or product is completely empty.
    // However, if the result is NaN, it implies no valid pixels were found for the mean, so C3 also covers that.
    const janCount = await janETImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: pakistan,
      scale: scale,
      maxPixels: maxPixels
    }).get('ET').getInfo();

    const augCount = await augETImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: pakistan,
      scale: scale,
      maxPixels: maxPixels
    }).get('ET').getInfo();

    if (janCount === 0 || augCount === 0) {
      console.log(`January valid pixels: ${janCount}`);
      console.log(`August valid pixels: ${augCount}`);
      console.log("C2"); // No Valid Pixels after processing
      return;
    }

    // 4. Validation & Final Answer
    console.log(`January 2018 Mean ET (mm): ${janMeanET.toFixed(2)} (Pixels: ${janCount})`);
    console.log(`August 2018 Mean ET (mm): ${augMeanET.toFixed(2)} (Pixels: ${augCount})`);

    if (augMeanET > janMeanET) {
      console.log("A"); // Yes, evapotranspiration increased
    } else {
      console.log("B"); // No, evapotranspiration did not increase (it decreased or stayed the same)
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log("D"); // General error/failure
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
